        menu_sequence: _sdT('Menu Sequence'), login: _sdT('Login'), ad: _sdT('Ad Region'),
        cart: _sdT('Cart'), tag_cloud: _sdT('Tag Cloud'), mobile_switch: _sdT('Mobile Switch'), pdf: _sdT('PDF'),
        comments_block: _sdT('Comments Block')
