    function googleFontUrl(name) {
        return 'https://fonts.googleapis.com/css2?family=' + encodeURIComponent(name).replace(/%20/g, '+') + ':wght@300;400;500;600;700&display=swap';
    }

    function injectGoogleFonts() {
        if (!canvasDoc) return;
        // Collect all fontFamily values in the current tree
        var used = {};
        (function walk(n) {
            if (n.props && n.props.fontFamily) used[n.props.fontFamily] = true;
            if (n.children) n.children.forEach(walk);
        })(tree);
        // Remove stale font links
        canvasDoc.querySelectorAll('link[data-gf]').forEach(function(l) {
            if (!used[l.dataset.gf]) l.remove();
        });
        // Inject missing font links
        Object.keys(used).forEach(function(name) {
            if (!canvasDoc.querySelector('link[data-gf="' + name + '"]')) {
                var lnk = canvasDoc.createElement('link');
                lnk.rel = 'stylesheet';
                lnk.dataset.gf = name;
                lnk.href = googleFontUrl(name);
                canvasDoc.head.appendChild(lnk);
            }
        });
    }

