        var currentLabel = node.props._label || '';
        labelWrap.innerHTML =
            '<div class="sd-tree-ctx-lbl-title"><i class="bi bi-tag"></i>' + esc(_sdT(' Label')) + '</div>' +
            '<input type="text" class="sd-tree-ctx-lbl-inp" placeholder="' + esc(_sdT('Designer note...')) + '" value="' + esc(currentLabel) + '">';
