                    var label = ff.label || ff.name || ('#' + ff.id);
                    if (ff.type) label += ' (' + ff.type + ')';
                    html += '<option value="' + esc(token) + '"' + (token === currentVal ? ' selected' : '') + '>' + esc(label) + '</option>';
