                'bi-hand-thumbs-up','bi-hdd','bi-hdd-fill','bi-hdd-network','bi-headphones','bi-headset','bi-heart',
                'bi-heart-fill','bi-house','bi-house-door','bi-house-door-fill','bi-house-fill','bi-image','bi-image-fill',
                'bi-images','bi-info','bi-info-circle','bi-info-circle-fill','bi-instagram','bi-journal','bi-journal-text',
                'bi-key','bi-key-fill','bi-keyboard','bi-laptop','bi-layout-sidebar','bi-layout-split',
