                'bi-steam','bi-stop','bi-stop-circle','bi-stop-fill','bi-sun','bi-sun-fill','bi-tablet','bi-tag',
                'bi-tag-fill','bi-tags','bi-telegram','bi-thermometer','bi-three-dots','bi-three-dots-vertical',
                'bi-tiktok','bi-toggle-off','bi-toggle-on','bi-tools','bi-translate','bi-trash','bi-trash-fill',
                'bi-trophy','bi-trophy-fill','bi-truck','bi-tv','bi-tv-fill','bi-twitter','bi-twitter-x',
                'bi-type','bi-type-bold','bi-type-h1','bi-type-h2','bi-type-h3','bi-type-italic','bi-type-underline',
                'bi-unlock','bi-upload','bi-usb','bi-volume-down','bi-volume-mute','bi-volume-up','bi-wallet',
