    // ========================= COMMAND PALETTE =========================
    function _getRecentCmds() {
        try { return JSON.parse(localStorage.getItem(RECENT_CMDS_KEY)) || []; } catch(e) { return []; }
    }

    function _trackRecentCmd(id, label, icon) {
        try {
            var list = _getRecentCmds().filter(function(c) { return c.id !== id; });
            list.unshift({ id: id, label: label, icon: icon || 'bi-dot' });
            if (list.length > MAX_RECENT_CMDS) list.length = MAX_RECENT_CMDS;
            localStorage.setItem(RECENT_CMDS_KEY, JSON.stringify(list));
        } catch(e) {}
    }

    function _fuzzyMatch(query, text) {
        if (!query) return true;
        var q = query.toLowerCase(), t = text.toLowerCase();
        if (t.indexOf(q) !== -1) return true;
        var qi = 0;
        for (var i = 0; i < t.length && qi < q.length; i++) { if (t[i] === q[qi]) qi++; }
        return qi === q.length;
    }

    function _paletteInsert(type, extra) {
        var target = selectedNode || tree;
        if (!target) return;
        if (!canDrop({ type: type }, target)) {
            target = tree;
            if (!canDrop({ type: type }, target)) return;
        }
        saveState();
        var n = createFromPalette(type, extra || {});
        if (!n) return;
        if (!target.children) target.children = [];
        target.children.push(n);
        selectedNode = n;
        expandAncestors(n, tree);
        render();
        _trackRecentComp(type, extra || {});
        var _cl = document.getElementById('sd-comp-list');
        if (_cl) _renderRecentCompSection(_cl);
    }

    function _getCpActionItems() {
        var items = [
            // ── Edit ────────────────────────────────────────────────
            { id: 'act_undo', label: _sdT('Undo'), icon: 'bi-arrow-counterclockwise', hint: 'Ctrl+Z', action: function() { undo(); } },
            { id: 'act_redo', label: _sdT('Redo'), icon: 'bi-arrow-clockwise', hint: 'Ctrl+Y', action: function() { redo(); } },
            { id: 'act_delete', label: _sdT('Delete'), icon: 'bi-trash', hint: 'Del', action: function() { if (selectedNode && selectedNode.type !== 'root' && !selectedNode.props._locked && !hasLockedAncestor(selectedNode)) onDelete(selectedNode); } },
            { id: 'act_duplicate', label: _sdT('Duplicate'), icon: 'bi-copy', hint: 'Ctrl+D', action: function() { if (selectedNode) onDuplicate(selectedNode); } },
            { id: 'act_copy', label: _sdT('Copy'), icon: 'bi-clipboard', hint: 'Ctrl+C', action: function() {
                var _tc = selectedNodes.length > 1 ? selectedNodes.slice() : (selectedNode ? [selectedNode] : []);
                if (_tc.length) clipboardNodes = _tc.map(function(n) { return cloneTree(n); });
            }},
            // ── Save / Preview / Snapshot ───────────────────────────
            { id: 'act_save', label: _sdT('Save'), icon: 'bi-floppy', hint: 'Ctrl+S', action: function() {
                var b = document.getElementById('sd-ajax-save'); if (b) b.click();
            }},
            { id: 'act_preview', label: _sdT('Preview'), icon: 'bi-box-arrow-up-right', hint: 'Ctrl+Alt+P', action: function() { openPreview(); } },
            { id: 'act_snapshot', label: _sdT('Take a Snapshot'), icon: 'bi-camera', action: function() { var n = window.prompt(_sdT('Snapshot name:')); if (n && n.trim()) saveSnapshot(n.trim()); } },
            // ── Selection ───────────────────────────────────────────
            { id: 'act_select_body', label: _sdT('Select the Body'), icon: 'bi-filetype-html', action: function() {
                if (!tree) return;
                selectedNode = tree;
                selectedNodes = [];
                renderSelectionOnly();
            }},
            { id: 'act_to_shared', label: _sdT('Convert to Shared Component'), icon: 'bi-puzzle-fill', action: function() {
                if (selectedNode && selectedNode.type !== 'root' && selectedNode.type !== 'shared_ref') convertToShared(selectedNode);
            }},
            // ── Settings / Modals ───────────────────────────────────
            { id: 'act_settings', label: _sdT('Open Settings'), icon: 'bi-gear', hint: 'Ctrl+,', action: function() {
                var b = document.querySelector('[data-bs-target="#styleSettingsModal"]');
                if (b) b.click();
            }},
            { id: 'act_grid', label: _sdT('Toggle Grid'), icon: 'bi-grid', action: function() { var b = document.getElementById('sd-vb-grid'); if (b) b.click(); } },
            { id: 'act_outline', label: _sdT('Toggle Outline'), icon: 'bi-grid-3x3', action: function() { var b = document.getElementById('sd-vb-outline'); if (b) b.click(); } },
            { id: 'act_shortcuts', label: _sdT('Keyboard Shortcuts'), icon: 'bi-question-circle', hint: '?', action: function() { openShortcutsModal(); } }
        ];

        // ── Assets-panel commands (only when the panel is mounted) ──
        if (_assetsApi) {
            items.push({ id: 'act_new_css',  label: _sdT('New CSS File'),  icon: 'bi-filetype-css',
                action: function() { _assetsApi.createFile('css');  } });
            items.push({ id: 'act_new_js',   label: _sdT('New JS File'),   icon: 'bi-filetype-js',
                action: function() { _assetsApi.createFile('js');   } });
            items.push({ id: 'act_new_json', label: _sdT('New JSON File'), icon: 'bi-filetype-json',
                action: function() { _assetsApi.createFile('json'); } });
            items.push({ id: 'act_upload_css', label: _sdT('Upload a CSS File'), icon: 'bi-upload',
                action: function() { _assetsApi.uploadFile('css'); } });
            items.push({ id: 'act_upload_js',  label: _sdT('Upload a JS File'),  icon: 'bi-upload',
                action: function() { _assetsApi.uploadFile('js');  } });
            items.push({ id: 'act_add_font',   label: _sdT('Add a Google Font'),  icon: 'bi-fonts',
                action: function() { _assetsApi.openGfModal(); } });

            // Sentinel toggles — labels reflect the current state.
            var states = _assetsApi.getSentinelStates();
            function _stateLabel(name, entry) {
                if (!entry) return name + ' (' + _sdT('none') + ')';
                return name + ' — ' + (entry.enabled === false ? _sdT('Activate') : _sdT('Deactivate'));
            }
            items.push({ id: 'act_tg_bs_css',   label: _stateLabel('Bootstrap CSS',    states.bsCss),    icon: 'bi-bootstrap',
                action: function() { _assetsApi.toggleSentinel('bootstrap-css');   } });
            items.push({ id: 'act_tg_bs_icons', label: _stateLabel('Bootstrap Icons',  states.bsIcons),  icon: 'bi-emoji-smile',
                action: function() { _assetsApi.toggleSentinel('bootstrap-icons'); } });
            items.push({ id: 'act_tg_bs_js',    label: _stateLabel('Bootstrap JS',     states.bsJs),     icon: 'bi-bootstrap-fill',
                action: function() { _assetsApi.toggleSentinel('bootstrap-js');    } });
            items.push({ id: 'act_tg_jquery',   label: _stateLabel('jQuery',           states.jquery),   icon: 'bi-code-slash',
                action: function() { _assetsApi.toggleSentinel('jquery-js');       } });
        }

        return items;
    }

    function _getCpPaletteItems() {
        var items = [];
        Object.keys(COMPONENTS).forEach(function(k) {
            var c = COMPONENTS[k];
            items.push({ id: 'add_comp_' + k, label: _sdT('Add: {var}', c.label), icon: c.icon || 'bi-plus',
                action: function() { _paletteInsert('component', { componentType: k }); } });
        });
        Object.keys(CONTENT).forEach(function(k) {
            // 'text' is a legacy/safety-net contentType — keep the registry entry for
            // rendering old DB records but hide it from the Command Palette.
            if (k === 'text') return;
            var c = CONTENT[k];
            items.push({ id: 'add_content_' + k, label: _sdT('Add: {var}', c.label), icon: c.icon || 'bi-plus',
                action: function() { _paletteInsert('content', { contentType: k }); } });
        });
        [['Container', 'container'], ['Row', 'row'], ['Column', 'col']].forEach(function(a) {
            items.push({ id: 'add_layout_' + a[1], label: _sdT('Add: {var}', a[0]), icon: 'bi-layout-split',
                action: function() { _paletteInsert(a[1], {}); } });
        });
        return items;
    }

    function _getCpTreeNodes() {
        var nodes = [];
        function traverse(node, depth) {
            if (node.type !== 'root') {
                nodes.push({ id: 'goto_' + node._id, label: getNodeLabel(node), icon: 'bi-cursor', depth: depth,
                    action: function() { scrollTreeToNode(node); selectedNode = node; selectedNodes = []; render(); }
                });
            }
            if (node.children) node.children.forEach(function(c) { traverse(c, depth + 1); });
        }
        traverse(tree, 0);
        return nodes;
    }

    function openCommandPalette() {
        if (_cmdPaletteEl) { closeCommandPalette(); return; }
        var overlay = document.createElement('div');
        overlay.className = 'sd-cp-overlay';
        overlay.id = 'sd-cmd-palette';
        _cmdPaletteEl = overlay;

        overlay.innerHTML =
            '<div class="sd-cp-modal">' +
            '<div class="sd-cp-search-row">' +
            '<span class="bi bi-search sd-cp-search-icon"></span>' +
            '<input type="text" class="sd-cp-input" id="sd-cp-input" placeholder="' + esc(_sdT('Search or type a command...')) + '" autocomplete="off" spellcheck="false">' +
            '<kbd class="sd-cp-esc-hint">Esc</kbd>' +
            '</div>' +
            '<div class="sd-cp-results" id="sd-cp-results"></div>' +
            '</div>';

        document.body.appendChild(overlay);

        var input = overlay.querySelector('#sd-cp-input');
        var results = overlay.querySelector('#sd-cp-results');
        var _activeIdx = -1;
        var _flatItems = [];

        function renderResults(q) {
            _flatItems = [];
            _activeIdx = -1;
            var html = '';

            function renderSection(title, items, maxShow) {
                var filtered = items.filter(function(it) { return _fuzzyMatch(q, it.label); });
                if (!filtered.length) return '';
                if (maxShow) filtered = filtered.slice(0, maxShow);
                var startIdx = _flatItems.length;
                _flatItems = _flatItems.concat(filtered);
                var sec = '<div class="sd-cp-section"><div class="sd-cp-section-title">' + title + '</div>';
                filtered.forEach(function(it, i) {
                    sec += '<div class="sd-cp-item" data-flat-idx="' + (startIdx + i) + '">' +
                        '<span class="bi ' + (it.icon || 'bi-dot') + ' sd-cp-item-icon"></span>' +
                        '<span class="sd-cp-item-label">' + esc(it.label) + '</span>' +
                        (it.hint ? '<kbd class="sd-cp-item-hint">' + esc(it.hint) + '</kbd>' : '') +
                        '</div>';
                });
                return sec + '</div>';
            }

            if (!q) {
                var recent = _getRecentCmds();
                if (recent.length) {
                    var allCmds = _getCpActionItems().concat(_getCpPaletteItems());
                    var recentResolved = recent.map(function(r) {
                        var found = allCmds.filter(function(a) { return a.id === r.id; })[0];
                        return found || { id: r.id, label: r.label, icon: r.icon, action: function() {} };
                    });
                    html += renderSection(_sdT('Recently Used'), recentResolved, 8);
                }
            }

            html += renderSection(_sdT('Commands'), _getCpActionItems());
            html += renderSection(_sdT('Add a Component'), _getCpPaletteItems(), q ? 20 : 10);
            html += renderSection(_sdT('Go to'), _getCpTreeNodes(), q ? 50 : 8);

            results.innerHTML = html || '<div class="sd-cp-empty">' + esc(_sdT('No results found')) + '</div>';

            results.querySelectorAll('.sd-cp-item').forEach(function(el) {
                el.addEventListener('mouseenter', function() {
                    _activeIdx = parseInt(this.dataset.flatIdx, 10);
                    highlightActive();
                });
                el.addEventListener('click', function() {
                    executeItem(parseInt(this.dataset.flatIdx, 10));
                });
            });

            if (_flatItems.length) { _activeIdx = 0; highlightActive(); }
        }

        function highlightActive() {
            results.querySelectorAll('.sd-cp-item').forEach(function(el) {
                el.classList.toggle('active', parseInt(el.dataset.flatIdx, 10) === _activeIdx);
            });
            var activeEl = results.querySelector('.sd-cp-item.active');
            if (activeEl) activeEl.scrollIntoView({ block: 'nearest' });
        }

        function executeItem(idx) {
            var item = _flatItems[idx];
            if (!item || !item.action) return;
            _trackRecentCmd(item.id, item.label, item.icon || 'bi-dot');
            item.action();
            closeCommandPalette();
        }

        input.addEventListener('input', function() { renderResults(this.value.trim()); });
        input.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') { e.preventDefault(); closeCommandPalette(); return; }
            if (e.key === 'ArrowDown') { e.preventDefault(); _activeIdx = Math.min(_activeIdx + 1, _flatItems.length - 1); highlightActive(); }
            else if (e.key === 'ArrowUp') { e.preventDefault(); _activeIdx = Math.max(_activeIdx - 1, 0); highlightActive(); }
            else if (e.key === 'Enter') { e.preventDefault(); executeItem(_activeIdx); }
        });
        overlay.addEventListener('click', function(e) { if (e.target === overlay) closeCommandPalette(); });

        renderResults('');
        setTimeout(function() { input.focus(); }, 10);
    }

    function closeCommandPalette() {
        if (_cmdPaletteEl) { _cmdPaletteEl.remove(); _cmdPaletteEl = null; }
    }

    // ========================= RECENTLY USED COMPS =========================
    function _getRecentComps() {
        try { return JSON.parse(localStorage.getItem(RECENT_COMPS_KEY)) || []; } catch(e) { return []; }
    }

    function _trackRecentComp(type, extra, hintLabel, hintIcon) {
        try {
            var id = type +
                (extra && extra.componentType ? ':' + extra.componentType : '') +
                (extra && extra.contentType   ? ':' + extra.contentType   : '') +
                (extra && extra.regionType    ? ':' + extra.regionType    : '') +
                (extra && extra.tag           ? ':' + extra.tag           : '');
            // Prefer a direct hint from the palette item (covers compound example types like
            // "hero-centered"/"navbar-mega" that aren't registered in COMPONENTS/CONTENT).
            var label = hintLabel || (type.charAt(0).toUpperCase() + type.slice(1));
            var icon = hintIcon || 'bi-plus';
            if (!hintLabel) {
                if (extra && extra.componentType && COMPONENTS[extra.componentType]) {
                    label = COMPONENTS[extra.componentType].label;
                    icon  = COMPONENTS[extra.componentType].icon || icon;
                } else if (extra && extra.contentType && CONTENT[extra.contentType]) {
                    label = CONTENT[extra.contentType].label;
                    icon  = CONTENT[extra.contentType].icon || icon;
                }
            }
            var list = _getRecentComps().filter(function(c) { return c.id !== id; });
            list.unshift({ id: id, label: label, icon: icon, type: type, extra: extra || {} });
            if (list.length > MAX_RECENT_COMPS) list.length = MAX_RECENT_COMPS;
            localStorage.setItem(RECENT_COMPS_KEY, JSON.stringify(list));
        } catch(e) {}
    }

    function _clearRecentComps() {
        try { localStorage.removeItem(RECENT_COMPS_KEY); } catch(e) {}
    }

